for _, n in ipairs({'R16_unorm', 'R16_snorm', 'R16_uscaled', 'R16_sscaled', 'R16_uint', 'R16_sint', 'R16_sfloat', 'R16G16B16A16_sfloat'}) do
    local t = {}
    for v = 0, 65535 do t[#t + 1] = string.pack('<I2', v) end
    local w = n:find('A16') and 128 or 256
    T.call('all16.' .. n, dec, table.concat(t), n, w, (n:find('A16') and 16384 or 65536) // w)
end
local f32, f64 = {}, {}
for k = 0, 256 do
    local b32 = string.unpack('<I4', string.pack('<f', k / 255))
    local b64 = string.unpack('<i8', string.pack('<d', k / 255))
    for d = -3, 3 do
        f32[#f32 + 1] = string.pack('<I4', (b32 + d) & 0xffffffff)
        f64[#f64 + 1] = string.pack('<i8', b64 + d < 0 and 0 or b64 + d)
    end
end
local specials = {1 / 0, -1 / 0, 0 / 0, 1e30, -1e30, 255.0, -0.0, 0.5}
for _, v in ipairs(specials) do f32[#f32 + 1] = string.pack('<f', v); f64[#f64 + 1] = string.pack('<d', v) end
T.call('bound.R32_sfloat', dec, table.concat(f32), 'R32_sfloat', #f32, 1)
T.call('bound.R64_sfloat', dec, table.concat(f64), 'R64_sfloat', #f64, 1)
T.call('bound.R32G32B32A32_sfloat', dec, table.concat(f32, '', 1, 1796), 'R32G32B32A32_sfloat', 449, 1)
T.call('bound.R64G64B64A64_sfloat', dec, table.concat(f64, '', 1, 1796), 'R64G64B64A64_sfloat', 449, 1)
for _, n in ipairs({'B10G11R11_ufloat_pack32', 'E5B9G9R9_ufloat_pack32'}) do
    local walk, mix = {}, {}
    for v = 0, 2047 do walk[#walk + 1] = string.pack('<I4', v); walk[#walk + 1] = string.pack('<I4', v << 11) end
    for v = 0, 1023 do walk[#walk + 1] = string.pack('<I4', v << 22) end
    for v = 0, 4095 do mix[#mix + 1] = string.pack('<I4', (v * 2654435761) & 0xffffffff) end
    T.call('walk.' .. n, dec, table.concat(walk), n, #walk, 1)
    T.call('mix.' .. n, dec, table.concat(mix), n, 64, 64)
end

